/**
 * Request and response shapes taken from the backend's OpenAPI schema.
 *
 * `schema.ts` is generated by `pnpm generate:types` from
 * `src/ptpd_calibration/api/openapi.json`, which CI regenerates and diffs, so
 * a route change that the client does not follow fails the build instead of
 * failing a user's request.
 *
 * Import request bodies from here rather than re-declaring them inline. Four
 * mismatches reached the default branch while these types went ungenerated:
 * the client sent `measurements` where the server reads `densities`, sent
 * `type` where the server reads `curve_type`, offered curve types the server
 * rejects, and treated a sampled response as the full curve.
 */

import type { components } from './schema';

export type ApiSchemas = components['schemas'];

/** Body of `POST /api/curves/generate`. */
export type CurveRequestBody = ApiSchemas['CurveRequest'];

/** Body of `POST /api/curves/modify`. */
export type CurveModifyRequestBody = ApiSchemas['CurveModifyRequest'];

/** Body of `POST /api/curves/smooth`. */
export type CurveSmoothRequestBody = ApiSchemas['CurveSmoothRequest'];

/** Body of `POST /api/analyze`. */
export type AnalyzeRequestBody = ApiSchemas['AnalyzeRequest'];
